import{_ as t,o as r,c as i,ae as a}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"GitHub: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/github.md","filePath":"adrs/1917971986/references/github.md"}'),o={name:"adrs/1917971986/references/github.md"};function n(s,e,c,l,p,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="github-hierarchy-audiences-and-access" tabindex="-1">GitHub: hierarchy, audiences, and access <a class="header-anchor" href="#github-hierarchy-audiences-and-access" aria-label="Permalink to &quot;GitHub: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>GitHub&#39;s structure places personal accounts and organizations as the accounts that can own repositories, with an enterprise account sitting above organizations as a container for several of them. GitHub states the enterprise account is &quot;the central point of administration for your business on GitHub&quot; and that it contains multiple organizations, while repositories and teams exist inside those organizations (<a href="https://docs.github.com/en/enterprise-cloud@latest/admin/overview/about-enterprise-accounts" target="_blank" rel="noreferrer">About enterprise accounts</a>).</p><p>Within an organization, teams can be nested: &quot;a parent team can have multiple child teams, while each child team only has one parent team,&quot; and GitHub supports multiple levels of nested teams. Secret teams are the exception and cannot be nested (<a href="https://docs.github.com/en/organizations/organizing-members-into-teams/about-teams" target="_blank" rel="noreferrer">About teams</a>).</p><p>Repositories are owned by a personal account or by an organization, and are not directly accessible under the enterprise account itself (<a href="https://docs.github.com/en/enterprise-cloud@latest/admin/overview/about-enterprise-accounts" target="_blank" rel="noreferrer">About enterprise accounts</a>).</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>The enterprise account is described as the administrative layer for identity (inviting or provisioning users and assigning them to organizations and teams), billing (including cost centers that allocate spending across business units), and policy (rules that govern repository creation, visibility, forking, and more across every organization the enterprise owns) (<a href="https://docs.github.com/en/enterprise-cloud@latest/admin/overview/about-enterprise-accounts" target="_blank" rel="noreferrer">About enterprise accounts</a>).</p><p>Work itself, meaning repositories, issues, and projects, lives inside organizations and personal accounts, not at the enterprise level (<a href="https://docs.github.com/en/enterprise-cloud@latest/admin/overview/about-enterprise-accounts" target="_blank" rel="noreferrer">About enterprise accounts</a>).</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>Repositories have three visibility levels. Public repositories are &quot;accessible to everyone on the internet.&quot; Private repositories are &quot;only accessible to you, people you explicitly share access with, and, for organization repositories, certain organization members.&quot; Internal repositories are available only in organizations owned by a GitHub Enterprise Cloud enterprise account (<a href="https://docs.github.com/en/repositories/creating-and-managing-repositories/about-repositories" target="_blank" rel="noreferrer">About repositories</a>).</p><p>Internal repositories extend read access across the whole enterprise: &quot;organization members have read permissions to all internal repositories in an enterprise, including those in organizations they are not a member of,&quot; while remaining invisible to anyone outside the enterprise, including outside collaborators on organization repositories (<a href="https://docs.github.com/en/enterprise-cloud@latest/repositories/creating-and-managing-repositories/about-repositories" target="_blank" rel="noreferrer">About repositories, GitHub Enterprise Cloud</a>).</p><p>GitHub Projects have a separate visibility switch, public or private. A public project can be viewed by &quot;everyone on the internet,&quot; while a private project can be seen only &quot;by users granted at least read access.&quot; Project visibility is independent of the visibility of the repositories whose items appear in it: viewing an item still requires access to the repository that item belongs to (<a href="https://docs.github.com/en/issues/planning-and-tracking-with-projects/managing-your-project/managing-visibility-of-your-projects" target="_blank" rel="noreferrer">Managing visibility of your projects</a>).</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>Organization owners can set base permissions, a default access level that applies to every organization member across all of the organization&#39;s repositories. Base permissions act as a floor: &quot;if someone with admin access to an organization&#39;s repository grants a member a higher level of access for the repository, the higher level of access overrides the base permission.&quot; The documentation describes granting higher access above the base level, and separately notes that internal repositories keep a minimum read-level visibility even when base permissions are set to none, which indicates the floor cannot be pushed below read for internal repositories (<a href="https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/setting-base-permissions-for-an-organization" target="_blank" rel="noreferrer">Setting base permissions for an organization</a>). Whether a repository can grant a member strictly less than the base permission for that repository specifically is not documented on this page.</p><p>At the repository level, forking can be narrowed further down the chain: people with admin permissions to a private repository can disallow forking of that repository, and separately, organization owners can disallow forking of any private repository in the organization (<a href="https://docs.github.com/en/pull-requests/reference/forks" target="_blank" rel="noreferrer">Forks</a>).</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Enterprise owners can enforce policies that cap what organizations may choose, rather than leaving every choice to the organization. For repository creation, the enterprise can restrict which visibilities members may create, restrict creation to organization owners only, or &quot;allow owners to administer the setting on the organization level,&quot; which is the non-enforced option. The same three-way pattern applies to who may change a repository&#39;s visibility, and to whether private or internal repositories may be forked at all, including an option to &quot;never allow forking of private or internal repositories&quot; across every organization the enterprise owns (<a href="https://docs.github.com/en/enterprise-cloud@latest/admin/enforcing-policies/enforcing-policies-for-your-enterprise/enforcing-repository-management-policies-in-your-enterprise" target="_blank" rel="noreferrer">Enforcing repository management policies in your enterprise</a>).</p><p>If repository creation is already restricted to organization owners only, members are also unable to change repository visibility, regardless of how the visibility-change policy itself is set (<a href="https://docs.github.com/en/enterprise-cloud@latest/admin/enforcing-policies/enforcing-policies-for-your-enterprise/enforcing-repository-management-policies-in-your-enterprise" target="_blank" rel="noreferrer">Enforcing repository management policies in your enterprise</a>). This is a ceiling that is opt-in per policy: an enterprise that leaves a policy on the organization-choice setting places no cap at all.</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>Primary documentation states what each visibility level permits, public, internal, or private, but does not describe a distinct discovery step in which someone without read access can see that a private or internal repository exists and request access to it. Private repository access is described only as something granted explicitly by an owner or collaborator (<a href="https://docs.github.com/en/repositories/creating-and-managing-repositories/about-repositories" target="_blank" rel="noreferrer">About repositories</a>). Not documented: an explicit request-access flow analogous to a discoverable but closed resource.</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>Organizations can exist on their own, with no enterprise account above them. Only when an organization is invited to and approved into an enterprise does it become subject to that enterprise&#39;s governance (<a href="https://docs.github.com/en/enterprise-cloud@latest/enterprise-onboarding/setting-up-organizations-and-teams/setting-up-an-organization" target="_blank" rel="noreferrer">Setting up an organization</a>). A one-organization customer therefore never has to interact with an enterprise account, identity provisioning, or enterprise-wide policy.</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>An existing organization can be added to an enterprise account. Enterprise owners invite the organization by name from enterprise settings, an owner of that organization approves the invitation, and the enterprise owner then approves the pending organization to complete the move (<a href="https://docs.github.com/en/enterprise-cloud@latest/enterprise-onboarding/setting-up-organizations-and-teams/setting-up-an-organization" target="_blank" rel="noreferrer">Setting up an organization</a>). An organization can be invited only if it does not already belong to another enterprise, and enterprises that use Enterprise Managed Users cannot add existing organizations at all (<a href="https://docs.github.com/en/enterprise-cloud@latest/enterprise-onboarding/setting-up-organizations-and-teams/setting-up-an-organization" target="_blank" rel="noreferrer">Setting up an organization</a>). Organizations with data residency enabled cannot move between GitHub.com and GHE.com enterprises through this invitation flow and instead require GitHub Enterprise Importer (<a href="https://docs.github.com/en/enterprise-cloud@latest/enterprise-onboarding/setting-up-organizations-and-teams/setting-up-an-organization" target="_blank" rel="noreferrer">Setting up an organization</a>).</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>The README&#39;s own table already maps GitHub&#39;s enterprise account to the governing role and GitHub&#39;s organization to the role that holds work. In this ADR&#39;s vocabulary that makes the enterprise account the Organization (tenant root, governing identity, billing, and policy) and a GitHub organization the Workspace (holds repositories, issues, and projects). Readers should not confuse this with GitHub&#39;s own use of the word &quot;organization,&quot; which names the Workspace role here, not the root.</li><li>GitHub has no typed, freely nestable Folder level between an organization and a repository. Teams nest, but teams group people, not work; repositories and projects attach directly to an organization. This is a divergence from the ADR, which allows optional folders between a workspace and a project.</li><li>Internal repository visibility matches the ADR&#39;s &quot;Organization&quot; audience closely: it grants read access to every member across every workspace (GitHub organization) under one root, exactly the audience the ADR calls &quot;every principal of the tenant, across all workspaces.&quot;</li><li>GitHub&#39;s base permissions behaving as a floor that a repository can raise, together with enterprise policy acting as an opt-in ceiling on organization choices, agrees with the ADR&#39;s rule that grants accumulate upward while limits bound downward and that root ceilings are opt-in per policy.</li><li>An organization existing with no enterprise account above it, and joining one later only through an explicit invitation and approval flow, agrees with the ADR&#39;s position that a small customer never meets the governing layer and that consolidation of separately created top-level accounts happens through deliberate migration, not an ordinary tree operation.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/enterprise-cloud@latest/admin/overview/about-enterprise-accounts" target="_blank" rel="noreferrer">About enterprise accounts</a></li><li><a href="https://docs.github.com/en/repositories/creating-and-managing-repositories/about-repositories" target="_blank" rel="noreferrer">About repositories</a></li><li><a href="https://docs.github.com/en/enterprise-cloud@latest/repositories/creating-and-managing-repositories/about-repositories" target="_blank" rel="noreferrer">About repositories, GitHub Enterprise Cloud</a></li><li><a href="https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/setting-base-permissions-for-an-organization" target="_blank" rel="noreferrer">Setting base permissions for an organization</a></li><li><a href="https://docs.github.com/en/enterprise-cloud@latest/admin/enforcing-policies/enforcing-policies-for-your-enterprise/enforcing-repository-management-policies-in-your-enterprise" target="_blank" rel="noreferrer">Enforcing repository management policies in your enterprise</a></li><li><a href="https://docs.github.com/en/pull-requests/reference/forks" target="_blank" rel="noreferrer">Forks</a></li><li><a href="https://docs.github.com/en/organizations/organizing-members-into-teams/about-teams" target="_blank" rel="noreferrer">About teams</a></li><li><a href="https://docs.github.com/en/enterprise-cloud@latest/enterprise-onboarding/setting-up-organizations-and-teams/setting-up-an-organization" target="_blank" rel="noreferrer">Setting up an organization</a></li><li><a href="https://docs.github.com/en/issues/planning-and-tracking-with-projects/managing-your-project/managing-visibility-of-your-projects" target="_blank" rel="noreferrer">Managing visibility of your projects</a></li></ul>',29)])])}const d=t(o,[["render",n]]);export{g as __pageData,d as default};
